<script setup lang="ts">import{Bot,CreditCard,MessageCircle,Smartphone,Users,Webhook}from"lucide-vue-next";definePageMeta({layout:"admin",middleware:"admin"});const{data,status}=await useFetch<any>("/api/admin/overview");const cards=computed(()=>[{l:"کل کاربران",v:data.value?.users,i:Users},{l:"کاربران فعال",v:data.value?.activeUsers,i:Users},{l:"اشتراک فعال",v:data.value?.subscriptions,i:CreditCard},{l:"واتساپ متصل",v:data.value?.sessions,i:Smartphone},{l:"کل پیام‌ها",v:data.value?.messages,i:MessageCircle},{l:"مصرف AI",v:data.value?.ai,i:Bot},{l:"وب‌هوک فعال",v:data.value?.webhooks,i:Webhook},{l:"درآمد",v:new Intl.NumberFormat().format(data.value?.revenue||0)+" تومان",i:CreditCard}]);</script><template><div><PageHeader title="داشبورد مدیریت" description="آمار واقعی کل سامانه"/><div v-if="status==='pending'">در حال بارگذاری...</div><section v-else class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article v-for="x in cards" :key="x.l" class="surface p-5"><span class="flex items-center justify-between text-sm text-slate-400">{{x.l}}<component :is="x.i" class="text-brand-600" :size="20"/></span><b class="mt-4 block text-2xl">{{x.v??0}}</b></article></section></div></template>
